  "f_cache_cold_title": "Context is being rebuilt more than it is reused",
  "f_cache_cold_body": "Only %PCT% of read tokens came from cache — below the %FLOOR% floor. Cache writes cost 1.25x input; cache reads cost 0.1x. Rebuilding is ~12x the price of reusing.",
  "f_cache_cold_action": "Keep working sessions alive instead of starting fresh ones. Batch related questions into one session, and avoid re-opening the same large files in new sessions.",
  "f_cache_write_never_read_title": "Sessions that paid to cache and then ended",
  "f_cache_write_never_read_body": "%N% session(s) wrote %WASTED% tokens to cache and never read one back — the 1.25x write premium paid for nothing.",
  "f_cache_write_never_read_action": "Ask the follow-ups in the same session — the second turn is where caching starts paying. These were closed right after the first big context load.",
  "f_premium_tier_light_turns_title": "Premium models are handling a lot of very short turns",
  "f_premium_tier_light_turns_body": "Across %TURNS% premium-tier turns the mean output is %AVG% tokens — below %THRESHOLD%. Short turns are usually acknowledgements, lookups, or mechanical edits, which a cheaper tier handles identically.",
  "f_premium_tier_light_turns_action": "Route mechanical work (file reads, renames, single-line edits, status checks) to Sonnet or Haiku, or run them at low effort. Keep the premium tier for the turns where reasoning depth actually changes the answer.",
  "f_read_heavy_no_change_title": "Sessions that read a lot and changed nothing",
