  "f_read_heavy_no_change_action1": "Delegate 'where is X' to a search subagent — the answer comes back without the file bodies.",
  "f_read_heavy_no_change_action2": "Ask the question you want answered rather than reading toward it.",
  "f_context_bloat_title": "Some sessions carry a very large context per turn",
  "f_context_bloat_body": "%N% session(s) peaked above %THRESHOLD% tokens on a single turn (worst: %WORST%), and every later turn re-reads it.",
  "f_context_bloat_action1": "Finish the thread and start the next piece of work in a fresh session.",
  "f_context_bloat_action2": "Carry forward only what that work needs — an exploration transcript dragged into unrelated work is what makes context this expensive.",
  "f_session_churn_title": "A large share of sessions are only a few turns long",
  "f_session_churn_body": "%SHORT% of %TOTAL% sessions (%PCT%) ended within %TURNS% turns. Short sessions never amortise their own context load — the cache write is paid, the reads never happen.",
  "f_session_churn_action": "Before starting a new session, check whether the question belongs to one you already have open. Treat a session as a workspace for a topic, not a container for a question.",
  "f_no_delegation_title": "No subagent delegation observed",
  "f_no_delegation_body": "Every token was produced in the main conversation. Subagents keep bulk reading out of your main context — the search happens elsewhere and only the conclusion comes back.",
  "f_no_delegation_action": "For broad 'find all the places that…' questions, delegate. The main context stays small, which keeps every later turn cheaper.",
  "f_subagent_fanout_title": "Most output is coming from subagents",
  "f_subagent_fanout_body": "%PCT% of all output tokens were produced by subagents. Delegation is good; delegation that re-establishes context per agent is not.",
