  "f_peak_window_immaterial_action": "Nothing to do now. Worth revisiting if your time-priced volume grows: the same percentage on ten times the tokens is ten times the premium.",
  "f_peak_window_arbitrage_title": "You are buying tokens at peak rates you did not have to pay",
  "f_peak_window_arbitrage_body": "%PCT% of your time-priced spend (%VENDORS%) ran inside a peak window, where the same tokens cost up to twice the off-peak rate. That timing cost about %PREMIUM% over the period.",
  "f_peak_window_arbitrage_action1": "Queue unattended work for an off-peak hour — test generation, migrations, doc sweeps, bulk refactors.",
