  "f_plan_under_used_action": "Either move down a tier, or move work onto the plan deliberately — the plan is already paid for, so anything you are still doing by hand is free to delegate until you cross the line.",
  "f_plan_value_realised_title": "%LABEL% returned about %MULT% what you paid for it",
