  "f_duplicated_turns_title": "Some turns are counted more than once",
  "f_duplicated_turns_body": "%DUPES% of %TOTAL% turns in the store (%SHARE%) are repeats of a turn already there, so every total on this page — turns, tokens and spend — is that much too high. This is a damaged store, not usage: an interrupted sync, two syncs at once, or a `sync --full` run before the repair landed. The duplicates are identical in provider, session, timestamp, turn and token counts, which is why they can be identified at all.",
  "f_duplicated_turns_action1": "Run `python3 observe.py dedupe`, then `python3 observe.py digest report`. It keeps the first copy of each turn and is safe on a healthy store.",
  "f_duplicated_turns_action2": "Re-read this page afterwards — expect roughly %SHARE% off every total.",
