  "f_unpriced_models_action1": "Add the model to observatory/pricing.json with the vendor's published rate and move `_verified_on` to today — CONTRIBUTING.md calls this the five-minute PR.",
  "f_unpriced_models_action2": "Until then, read the %SHARE% as unmeasured rather than as spend.",

