  "f_plan_under_used_body": "過去 %DAYS% 日間、あなたの利用量は従量制APIレートで見るとおよそ %API%/月分の価値でした。支払っているのは %PAID%/月。使い切れていない余裕分にお金を払っています。",
  "f_plan_under_used_action": "1つ下のプランに移すか、意図的にもっと多くの作業をこのプランに載せてください——プラン代はすでに払っているので、まだ手作業でこなしていることは、その線を超えるまで無料で委任できます。",
  "f_plan_value_realised_title": "%LABEL% は支払った分の約 %MULT% を返している",
  "f_plan_value_realised_body": "過去 %DAYS% 日間、あなたの利用量は従量制APIレートで見るとおよそ %API%/月分の価値で、%PAID%/月のプランに対してこの結果です。このページの他のドル表示はすべて影の価格——従量制ならいくらかかったか——であり、実際に受け取った請求書ではありません。",
  "f_plan_value_realised_action": "対応不要。プランを変更したあとは再確認する価値があり、より大きなプランを求める前に知っておく価値もあります。",
  "f_vendor_mix_healthy_title": "作業が複数の提供元に分散している",
  "f_vendor_mix_healthy_body": "最大の提供元は %TOP% で、出力トークンの %PCT% を占め、全体では %N% 社にまたがっています。",
  "f_vendor_mix_healthy_action": "対応不要。複数を組み合わせておくことで、ワークフローを学び直さずに価格交渉先を変えたり乗り換えたりできます。",
  "f_vendor_concentration_title": "ほぼすべての作業が %TOP% 経由で動いている",
  "f_vendor_concentration_body": "出力トークンの %PCT% が %TOP% から来ています。この提供元の値上げ、地域での提供停止、障害はすべて、あなたのワークフロー全体にとっての単一障害点になります——しかも乗り換えのコストを比べるための基準となる実測値がありません。",
  "f_vendor_concentration_action": "低リスクで繰り返し発生する作業（テストの雛形、コミットメッセージ、ドキュメント更新）を1種類選び、2週間ほど別の提供元で回してみてください。目的はすぐに節約することではなく、いざ乗り換えを迫られる前にそのコストを知っておくことです。",
  "f_local_currency_title": "あなたの地域で見た場合のコスト",
  "f_local_currency_body": "plans.json のレートで換算すると、月あたりおよそ %USD%。%TAIL%",
  "f_local_currency_action": "対応不要。このリポジトリの為替レートは目安として手動で保守されているものです——正確な会計ではなく、感覚的な目安として扱ってください。",
  "f_duplicated_turns_title": "一部のターンが重複してカウントされている",
  "f_duplicated_turns_body": "ストア内の %TOTAL% ターンのうち %DUPES% 件（%SHARE%）は既存ターンの重複で、そのぶんこのページ上のすべての合計——ターン数、トークン数、支出——が高くなっています。これは利用量ではなく壊れたストアの問題です：同期の中断、同時に走った2つの同期、あるいは修正が入る前に実行された `sync --full` のいずれかが原因です。重複はプロバイダー、セッション、タイムスタンプ、ターン、トークン数がすべて一致しており、それゆえ特定できています。",
  "f_duplicated_turns_action1": "`python3 observe.py dedupe` を実行し、続けて `python3 observe.py digest report` を実行してください。各ターンの最初のコピーを残す処理で、健全なストアで実行しても安全です。",
  "f_duplicated_turns_action2": "そのあとこのページを見直してください——各合計がおよそ %SHARE% 下がるはずです。",
  "f_unpriced_models_title": "この推定値の一部は推測に基づいている",
  "f_unpriced_models_body": "推定支出のうち %SHARE%（%TURNS% ターンで %COST%）は、レートカードに載っていないモデルによるものです：%NAMED%。これらのターンは汎用のフォールバック価格——入力 %FB_IN%/M、出力 %FB_OUT%/M——で計算されており、これは仮の値であって、そのベンダーの公表レートではありません。誤差がどちら方向に振れているかは、ページの他の部分からはわかりません。",
  "f_unpriced_models_action1": "そのモデルを observatory/pricing.json に、ベンダーが公表しているレートとともに追加し、`_verified_on` を今日の日付に更新してください——CONTRIBUTING.md ではこれを「5分でできるPR」と呼んでいます。",
  "f_unpriced_models_action2": "それまでは、この %SHARE% を支出としてではなく、未計測分として読んでください。",

