  "ph_note": "समय-आधारित मूल्य वाले व्यय का <strong>%P%</strong> पीक विंडो में पड़ा। वही टर्न ऑफ-पीक में चलाने पर %T% के बजाय %F% लगता — समय के कारण <strong>%X%</strong> अतिरिक्त।",
  "ph_batch": "बैच काम — टेस्ट जनरेशन, माइग्रेशन, डॉक्युमेंट सफ़ाई — वह हिस्सा है जिसे आपकी निगरानी नहीं चाहिए, इसलिए यही हटाने लायक है।",
  "mon": "जन,फ़र,मार्च,अप्रैल,मई,जून,जुल,अग,सित,अक्तू,नव,दिस",
  meth_h2: "यह आँकड़ा कैसे नापा गया",
  meth_1: "<strong>प्रॉम्प्ट, जवाब, फ़ाइल कॉन्टेंट, कमांड या पाथ — इनमें से कुछ भी कभी सहेजा या दिखाया नहीं जाता।</strong> सिर्फ़ गिनतियाँ, मॉडल के नाम, टूल के नाम, और निकाले गए रिपॉज़िटरी/फ़ोल्डर लेबल रखे जाते हैं — जो API द्वारा पहले से लौटाए गए टोकन हिसाब से, स्थानीय Claude Code और Codex ट्रांसक्रिप्ट से पढ़े जाते हैं। जमा करने में कोई टोकन ख़र्च नहीं होता।",
  star_ask: "क्या यहाँ बदलने लायक कुछ मिला?",
  star_ask_cta: "GitHub पर स्टार दें",
  demo_chip: "नमूना डेटा",
  demo_try: "खुद आज़माएँ",
  meth_2: "<strong>लागत एक अनुमान है, बिल नहीं।</strong> टोकन गिनती सटीक है; डॉलर के आँकड़े हर वेंडर का सार्वजनिक API सूची-मूल्य लागू करते हैं (सत्यापित %V%) — यह अधिकतम दर है, एंटरप्राइज़ या सब्सक्रिप्शन छूट से पहले की। ख़र्च को अधिकतम सीमा की तरह लें, और यह देखने के <em>सापेक्ष</em> संकेत की तरह कि मेहनत कहाँ जा रही है।",
  meth_3: "<strong>काम का श्रेय अकाउंट को नहीं, रिपॉज़िटरी को मिलता है।</strong> कोई टर्न उस रिपॉज़िटरी से जुड़ता है जिसे उसने छुआ, या उसी सत्र में सबसे नज़दीकी श्रेय-प्राप्त टर्न को आगे बढ़ाता है; जिस सत्र ने कोई फ़ाइल नहीं छुई वह <code>unattributed</code> ही रहता है, और स्क्रैच या कॉन्फ़िग फ़ोल्डर असली रिपॉज़िटरी से नहीं जुड़ते। लेन उस नियम से तय होती है जो आपने ख़ुद <code>engine/topology.json</code> में लिखा — ट्रांसक्रिप्ट में कोई अकाउंट पहचान नहीं होती।",
  meth_4: "<strong>यह पेज ख़ुद में पूरा और दोबारा बनाने लायक़ है।</strong> कोई बाहरी रिक्वेस्ट, फ़ॉन्ट, स्क्रिप्ट या एनालिटिक्स नहीं। %G% UTC पर जनरेट हुआ — कभी भी <code>python3 engine/observe.py all</code> से दोबारा बना लें।",
  // --- findings i18n (translateFindings) -----------------------------------
  "finds_empty": "अभी कोई निष्कर्ष नहीं — कुछ और दिनों का उपयोग डेटा जमा होने दें।",
  "sev_high": "उच्च",
