  "sev_low": "कम",
  "sev_info": "जानकारी",
  "conf_label": "भरोसे का स्तर:",
  "conf_high": "उच्च",
  "conf_medium": "मध्यम",
  "conf_low": "कम",
  "save_permo": "≈%V%/माह",
  "demoted_note": "बात सच है, पर इस मात्रा में असर मामूली है (लगभग %V%/माह)। इसे इसलिए रखा गया है ताकि यह पैटर्न बढ़ने से पहले आपको दिख जाए।",
  "f_and_others": "और अन्य",
  "f_local_currency_tail": "यह स्थानीय डेवलपर कॉन्ट्रैक्ट दर के लगभग %D% दिनों के बराबर है — यही तय करता है कि यह महँगा है या नहीं।",
  "f_cache_healthy_title": "कैश अपना काम अच्छे से कर रहा है",
  "f_cache_healthy_body": "मॉडलों ने जो कुछ पढ़ा, उसमें से %PCT% कैश से आया, पूरी कीमत पर दोबारा नहीं बिला।",
  "f_cache_healthy_action": "कोई कार्रवाई ज़रूरी नहीं। इस आँकड़े पर नज़र रखें — गिरावट का मतलब है कि सेशन ज़्यादा बार दोबारा शुरू हो रहे हैं।",
  "f_cache_cold_title": "संदर्भ (context) दोबारा इस्तेमाल होने से ज़्यादा दोबारा बनाया जा रहा है",
  "f_cache_cold_body": "पढ़े गए टोकन में से सिर्फ़ %PCT% कैश से आए — %FLOOR% की सीमा से नीचे। कैश लिखना इनपुट दर का 1.25 गुना और कैश पढ़ना 0.1 गुना पड़ता है, यानी दोबारा बनाना दोबारा इस्तेमाल करने से लगभग 12 गुना महँगा है।",
  "f_cache_cold_action": "नए सिरे से सेशन शुरू करने के बजाय काम के सेशन को ज़िंदा रखें। जुड़े हुए सवालों को एक ही सेशन में रखें, और नए सेशन में वही बड़ी फ़ाइलें दोबारा खोलने से बचें।",
  "f_cache_write_never_read_title": "जिन सेशनों ने कैश में पैसे लगाए और फिर बंद हो गए",
  "f_cache_write_never_read_body": "%N% सेशन(नों) ने %WASTED% टोकन कैश में लिखे और कभी वापस नहीं पढ़े — 1.25 गुना लिखने का अतिरिक्त शुल्क बेकार गया।",
  "f_cache_write_never_read_action": "आगे के सवाल उसी सेशन में पूछें — कैश का फ़ायदा दूसरे टर्न से मिलना शुरू होता है। ये सेशन पहली बड़ी संदर्भ लोडिंग के तुरंत बाद बंद कर दिए गए।",
  "f_premium_tier_light_turns_title": "प्रीमियम मॉडल बहुत सारे बहुत छोटे टर्न संभाल रहे हैं",
  "f_premium_tier_light_turns_body": "%TURNS% प्रीमियम-स्तर के टर्न में औसत आउटपुट %AVG% टोकन है — %THRESHOLD% से कम। छोटे टर्न अक्सर पावती, लुकअप या मशीनी संपादन होते हैं, जिन्हें सस्ता स्तर भी उतनी ही अच्छी तरह संभाल सकता है।",
  "f_premium_tier_light_turns_action": "मशीनी काम (फ़ाइल पढ़ना, नाम बदलना, एक-लाइन संपादन, स्टेटस जाँचना) Sonnet या Haiku को दें, या कम रीज़निंग स्तर पर चलाएँ। प्रीमियम स्तर उन्हीं टर्न के लिए रखें जहाँ रीज़निंग की गहराई वाक़ई जवाब बदलती है।",
  "f_read_heavy_no_change_title": "जो सेशन बहुत पढ़े पर कुछ नहीं बदला",
  "f_read_heavy_no_change_body": "%N% सेशन(नों) ने बिना किसी संपादन या लेखन के %READS% रीड-टाइप टूल कॉल किए, जिसमें %COST% USD खर्च हुए। कुछ वाक़ई शोध है; कुछ वह ढूँढते हुए भटकना है जो एक सटीक खोज तुरंत दे देती।",
  "f_read_heavy_no_change_action1": "'X कहाँ है' जैसे सवाल सर्च सब-एजेंट को सौंपें — फ़ाइल की पूरी सामग्री के बिना सीधा जवाब वापस आता है।",
  "f_read_heavy_no_change_action2": "पढ़-पढ़कर ढूँढने के बजाय, वह सवाल सीधे पूछें जिसका जवाब चाहिए।",
  "f_context_bloat_title": "कुछ सेशन हर टर्न में बहुत बड़ा संदर्भ ढोते हैं",
  "f_context_bloat_body": "%N% सेशन(नों) ने एक ही टर्न में %THRESHOLD% टोकन से ज़्यादा का शिखर छुआ (सबसे ज़्यादा: %WORST%), और बाद का हर टर्न उसे दोबारा पढ़ता है।",
  "f_context_bloat_action1": "उस विषय को पूरा करें और अगला काम एक नए सेशन में शुरू करें।",
  "f_context_bloat_action2": "सिर्फ़ वही आगे ले जाएँ जिसकी उस काम को ज़रूरत है — किसी असंबंधित काम में खोजबीन का पूरा ब्यौरा घसीट लाना ही संदर्भ को इतना महँगा बना देता है।",
  "f_session_churn_title": "काफ़ी सारे सेशन बस कुछ ही टर्न लंबे हैं",
  "f_session_churn_body": "%TOTAL% में से %SHORT% सेशन (%PCT%) %TURNS% टर्न के अंदर ही ख़त्म हो गए। छोटे सेशन कभी अपने संदर्भ लोडिंग की लागत नहीं वसूल पाते — कैश लिखने का पैसा चुका दिया जाता है, पर पढ़ने का मौक़ा कभी नहीं आता।",
  "f_session_churn_action": "नया सेशन शुरू करने से पहले देखें कि यह सवाल किसी पहले से खुले सेशन का हिस्सा तो नहीं है। सेशन को किसी एक सवाल का डिब्बा नहीं, किसी विषय के लिए कार्यक्षेत्र मानें।",
  "f_no_delegation_title": "कोई सब-एजेंट सौंपा जाना नहीं दिखा",
