  meth_2: "<strong>Biaya adalah perkiraan, bukan tagihan.</strong> Jumlah token bersifat pasti; angka dolar memakai harga daftar API publik tiap vendor (diverifikasi %V%) — tarif tertinggi yang dibayar siapa pun, sebelum diskon enterprise atau langganan. Perlakukan pengeluaran sebagai batas atas, dan sebagai sinyal <em>relatif</em> ke mana usaha mengalir.",
