  "f_cache_cold_body": "Hanya %PCT% token yang dibaca berasal dari cache — di bawah batas %FLOOR%. Penulisan cache berbiaya 1,25x tarif input; pembacaan cache 0,1x. Membangun ulang berbiaya ~12x lebih mahal daripada memakai ulang.",
  "f_cache_cold_action": "Biarkan sesi kerja tetap berjalan alih-alih memulai yang baru. Kumpulkan pertanyaan terkait dalam satu sesi, dan hindari membuka ulang berkas besar yang sama di sesi baru.",
