  "f_cache_write_never_read_body": "%N% sesi menulis %WASTED% token ke cache dan tidak pernah membacanya kembali — premi penulisan 1,25x itu tidak menghasilkan apa-apa.",
  "f_cache_write_never_read_action": "Ajukan pertanyaan lanjutan di sesi yang sama — giliran kedualah yang mulai membuat cache terbayar. Sesi-sesi ini ditutup tepat setelah memuat konteks besar pertama.",
  "f_premium_tier_light_turns_title": "Model premium menangani banyak giliran yang sangat singkat",
  "f_premium_tier_light_turns_body": "Di %TURNS% giliran tingkat premium, rata-rata output adalah %AVG% token — di bawah %THRESHOLD%. Giliran singkat biasanya berupa konfirmasi, pencarian, atau suntingan mekanis, yang bisa ditangani sama baiknya oleh tingkat yang lebih murah.",
  "f_premium_tier_light_turns_action": "Alihkan pekerjaan mekanis (membaca berkas, mengganti nama, suntingan satu baris, pengecekan status) ke Sonnet atau Haiku, atau jalankan pada usaha rendah. Simpan tingkat premium untuk giliran yang kedalaman penalarannya benar-benar mengubah jawaban.",
  "f_read_heavy_no_change_title": "Sesi yang banyak membaca dan tidak mengubah apa pun",
  "f_read_heavy_no_change_body": "%N% sesi melakukan %READS% panggilan alat bertipe baca tanpa satu pun penyuntingan atau penulisan, dengan biaya %COST% USD. Sebagian memang riset asli; sebagian lagi mencari-cari apa yang bisa langsung ditemukan pencarian yang tepat sasaran.",
  "f_read_heavy_no_change_action1": "Delegasikan 'di mana X' ke subagen pencarian — jawabannya kembali tanpa isi berkas.",
  "f_read_heavy_no_change_action2": "Tanyakan langsung apa yang ingin Anda ketahui, alih-alih membaca sambil meraba-raba.",
  "f_context_bloat_title": "Beberapa sesi membawa konteks yang sangat besar per giliran",
  "f_context_bloat_body": "%N% sesi mencapai puncak di atas %THRESHOLD% token dalam satu giliran (terburuk: %WORST%), dan setiap giliran berikutnya membacanya ulang.",
  "f_context_bloat_action1": "Selesaikan topik itu dan mulai pekerjaan berikutnya di sesi baru.",
  "f_context_bloat_action2": "Bawa hanya apa yang benar-benar dibutuhkan pekerjaan itu — menyeret transkrip eksplorasi ke pekerjaan yang tidak berhubungan itulah yang membuat konteks semahal ini.",
  "f_session_churn_title": "Sebagian besar sesi hanya berlangsung beberapa giliran",
  "f_session_churn_body": "%SHORT% dari %TOTAL% sesi (%PCT%) berakhir dalam %TURNS% giliran. Sesi pendek tidak pernah mengamortisasi biaya pemuatan konteksnya sendiri — biaya penulisan cache sudah dibayar, pembacaannya tidak pernah terjadi.",
  "f_session_churn_action": "Sebelum memulai sesi baru, cek apakah pertanyaan itu sebenarnya milik sesi yang sudah terbuka. Perlakukan sesi sebagai ruang kerja untuk satu topik, bukan wadah untuk satu pertanyaan.",
