  "f_no_delegation_body": "Setiap token dihasilkan dalam percakapan utama. Subagen menjaga pembacaan besar-besaran tetap di luar konteks utama — pencarian terjadi di tempat lain dan hanya kesimpulannya yang kembali.",
  "f_no_delegation_action": "Untuk pertanyaan luas seperti 'temukan semua tempat yang…', delegasikan. Konteks utama tetap kecil, membuat setiap giliran berikutnya lebih murah.",
