  "f_delegation_balanced_title": "Pendelegasian ke subagen tampak proporsional",
  "f_delegation_balanced_body": "%PCT% dari output berasal dari subagen — cukup untuk menjaga pembacaan besar-besaran di luar konteks utama tanpa fan-out yang berlebihan.",
  "f_delegation_balanced_action": "Tidak perlu tindakan.",
  "f_cache_1h_justified_title": "Caching TTL panjang terbayar",
  "f_cache_1h_justified_body": "%PCT% penulisan cache menggunakan TTL 1 jam, dan setiap token yang ditulis dibaca kembali rata-rata %RATIO% kali — di atas titik impas ~3x untuk premi penulisan 2x.",
  "f_cache_1h_justified_action": "Tidak perlu tindakan.",
  "f_cache_1h_underused_title": "Penulisan cache TTL panjang tidak cukup sering dibaca ulang untuk terbayar",
  "f_cache_1h_underused_body": "%PCT% penulisan cache menggunakan TTL 1 jam (tarif 2x input) tetapi token yang ditulis hanya dibaca kembali %RATIO% kali. TTL 1 jam butuh kira-kira tiga kali pembacaan untuk mengalahkan TTL 5 menit.",
  "f_cache_1h_underused_action": "Ini sinyal soal panjang sesi, bukan pengaturan yang perlu diubah: TTL panjang ada agar Anda bisa kembali setelah jeda. Jika Anda tidak kembali, masalahnya ada pada jeda itu sendiri.",
