  "f_tool_concentration_action": "Periksa apa yang diulang-ulang oleh %TOOL%. Target yang sama dua kali dalam satu sesi adalah konteks yang sebenarnya sudah Anda miliki.",
  "f_where_the_time_goes_title": "Di mana investasi AI Anda terpusat",
