  "f_where_the_time_goes_action": "Bandingkan urutan ini dengan apa yang menurut Anda menjadi prioritas. Ruang kerja yang tinggi di daftar ini tapi rendah dalam prioritas Anda sendiri — itulah temuannya.",
  "f_working_rhythm_title": "Kapan Anda sebenarnya menggunakan AI",
