  "f_peak_window_healthy_body": "Hanya %PCT% dari pengeluaran %VENDORS% Anda yang jatuh dalam jendela puncak. Premi yang Anda bayar untuk waktu itu sekitar %PREMIUM% selama periode ini.",
  "f_peak_window_healthy_action": "Tidak perlu tindakan. Ini angka yang perlu dipantau jika Anda mulai menjadwalkan pekerjaan batch.",
