  "f_peak_window_immaterial_action": "Tidak ada yang perlu dilakukan sekarang. Layak ditinjau ulang jika volume bertarif waktu Anda bertambah: persentase yang sama pada sepuluh kali lipat token berarti premi sepuluh kali lipat.",
  "f_peak_window_arbitrage_title": "Anda membeli token dengan tarif puncak yang sebenarnya tidak perlu dibayar",
  "f_peak_window_arbitrage_body": "%PCT% pengeluaran bertarif waktu Anda (%VENDORS%) berjalan dalam jendela puncak, tempat token yang sama bisa berbiaya hingga dua kali tarif luar puncak. Waktu itu berbiaya sekitar %PREMIUM% selama periode ini.",
  "f_peak_window_arbitrage_action1": "Antre pekerjaan tanpa pengawasan untuk jam luar puncak — pembuatan tes, migrasi, perapian dokumen, refactor besar.",
