  "f_peak_window_arbitrage_action3": "Jendela-jendela ini sempit — DeepSeek 01:00-04:00 dan 06:00-10:00 UTC, GLM 14:00-18:00 UTC+8 pada hari kerja, jadi akhir pekan sepenuhnya bebas dari itu.",
