  "f_plan_under_used_action": "Turunkan tingkat paket, atau alihkan lebih banyak pekerjaan ke paket ini secara sengaja — paket sudah dibayar, jadi apa pun yang masih Anda kerjakan sendiri boleh didelegasikan tanpa biaya tambahan sampai batasnya terlampaui.",
