  "f_plan_value_realised_body": "Selama %DAYS% hari, pemakaian Anda bernilai sekitar %API%/bulan pada tarif API meteran, dibandingkan paket %PAID%/bulan. Angka dolar di tempat lain di halaman ini adalah harga bayangan — perkiraan biaya jika diukur per pemakaian — bukan tagihan yang benar-benar Anda terima.",
  "f_plan_value_realised_action": "Tidak perlu tindakan. Layak dicek ulang setelah perubahan tingkat paket, dan layak diketahui sebelum meminta paket yang lebih besar.",
