  "f_vendor_mix_healthy_body": "%TOP% adalah yang terbesar dengan %PCT% dari token output, di antara total %N% penyedia.",
  "f_vendor_mix_healthy_action": "Tidak perlu tindakan. Kombinasi inilah yang memungkinkan Anda menegosiasikan ulang harga atau berpindah tanpa harus mempelajari ulang alur kerja.",
  "f_vendor_concentration_title": "Hampir semua pekerjaan berjalan lewat %TOP%",
  "f_vendor_concentration_body": "%PCT% token output Anda berasal dari %TOP%. Perubahan tarif, ketersediaan regional, dan gangguan pada satu penyedia semuanya menjadi titik kegagalan tunggal untuk seluruh alur kerja Anda — dan Anda tidak punya baseline terukur untuk membandingkan biaya berpindah.",
  "f_vendor_concentration_action": "Jalankan satu jenis pekerjaan berisiko rendah yang berulang (rangka tes, pesan commit, pembaruan dokumen) di penyedia kedua selama dua minggu. Tujuannya bukan menghemat uang segera; melainkan mengetahui biaya berpindah sebelum Anda terpaksa melakukannya.",
  "f_local_currency_title": "Berapa biayanya di tempat Anda",
