  "f_duplicated_turns_body": "%DUPES% dari %TOTAL% giliran dalam penyimpanan (%SHARE%) adalah pengulangan giliran yang sudah ada, sehingga setiap total di halaman ini — giliran, token, dan pengeluaran — terlalu tinggi sebesar itu. Ini penyimpanan yang rusak, bukan pemakaian: sinkronisasi yang terputus, dua sinkronisasi bersamaan, atau `sync --full` yang dijalankan sebelum perbaikan diterapkan. Duplikat ini identik dalam penyedia, sesi, stempel waktu, giliran, dan jumlah token, itulah sebabnya bisa dikenali.",
  "f_duplicated_turns_action1": "Jalankan `python3 observe.py dedupe`, lalu `python3 observe.py digest report`. Perintah ini menyimpan salinan pertama dari setiap giliran dan aman dijalankan pada penyimpanan yang sehat.",
