  meth_2: "<strong>ต้นทุนเป็นค่าประมาณ ไม่ใช่ใบเรียกเก็บเงิน</strong> จำนวนโทเคนแม่นยำ ส่วนตัวเลขดอลลาร์ใช้ราคา API ตามบัญชีราคาสาธารณะของแต่ละผู้ให้บริการ (ตรวจสอบเมื่อ %V%) ซึ่งเป็นอัตราสูงสุดที่มีใครจ่าย ก่อนส่วนลดองค์กรหรือแบบสมัครสมาชิก ให้มองค่าใช้จ่ายเป็นเพดานราคา และเป็นสัญญาณ<em>เชิงเปรียบเทียบ</em>ว่าแรงงานไปตกอยู่ที่ใด",
  meth_3: "<strong>การนับเจ้าของงานยึดตามที่เก็บโค้ด ไม่ใช่ตามบัญชี</strong> แต่ละรอบจะนับเป็นของที่เก็บโค้ดที่มันแตะถึง หรือรับช่วงจากรอบที่นับเจ้าของล่าสุดในเซสชันเดียวกัน เซสชันที่ไม่แตะไฟล์ใดเลยจะยังคงเป็น <code>unattributed</code> และโฟลเดอร์ scratch หรือ config จะไม่ผูกกับที่เก็บโค้ดจริง ช่องทางมาจากกฎที่คุณเขียนเองใน <code>engine/topology.json</code> — บันทึกไม่มีข้อมูลระบุตัวตนบัญชีเลย",
  meth_4: "<strong>หน้านี้สมบูรณ์ในตัวเองและสร้างซ้ำได้</strong> ไม่มีการเรียกข้อมูลภายนอก ไม่มีฟอนต์ สคริปต์ หรือการวิเคราะห์ใด ๆ สร้างเมื่อ %G% UTC — สร้างใหม่ได้ทุกเมื่อด้วย <code>python3 engine/observe.py all</code>",
