  "f_premium_tier_light_turns_title": "โมเดลระดับพรีเมียมกำลังรับมือกับเทิร์นสั้น ๆ จำนวนมาก",
  "f_premium_tier_light_turns_body": "จาก %TURNS% เทิร์นในระดับพรีเมียม ค่าเฉลี่ยเอาต์พุตอยู่ที่ %AVG% โทเคน — ต่ำกว่า %THRESHOLD% เทิร์นสั้น ๆ มักเป็นการตอบรับ การค้นหา หรือการแก้ไขเชิงกลไก ซึ่งระดับที่ถูกกว่าก็ทำได้เหมือนกัน",
  "f_premium_tier_light_turns_action": "ส่งงานเชิงกลไก (อ่านไฟล์ เปลี่ยนชื่อ แก้บรรทัดเดียว ตรวจสถานะ) ไปที่ Sonnet หรือ Haiku หรือรันด้วยระดับการใช้เหตุผลต่ำ เก็บระดับพรีเมียมไว้สำหรับเทิร์นที่ความลึกของการใช้เหตุผลเปลี่ยนคำตอบจริง ๆ",
  "f_read_heavy_no_change_title": "เซสชันที่อ่านเยอะแต่ไม่ได้เปลี่ยนอะไรเลย",
  "f_read_heavy_no_change_body": "%N% เซสชันเรียกใช้เครื่องมือประเภทอ่าน %READS% ครั้งโดยไม่มีการแก้ไขหรือเขียนเลย เสียค่าใช้จ่าย %COST% USD บางส่วนเป็นการค้นคว้าจริง บางส่วนเป็นการค้นหาแบบเดาทางสิ่งที่การค้นหาแบบตรงเป้าจะหาเจอได้ทันที",
  "f_read_heavy_no_change_action1": "มอบคำถามแบบ 'X อยู่ที่ไหน' ให้ subagent ค้นหา — คำตอบจะกลับมาโดยไม่พ่วงเนื้อหาไฟล์ทั้งหมด",
  "f_read_heavy_no_change_action2": "ถามคำตอบที่ต้องการโดยตรง แทนที่จะอ่านไปเรื่อย ๆ เพื่อค้นหามัน",
