  "f_context_bloat_body": "%N% เซสชันมีจุดสูงสุดเกิน %THRESHOLD% โทเคนในเทิร์นเดียว (สูงสุด: %WORST%) และทุกเทิร์นหลังจากนั้นต้องอ่านซ้ำทั้งหมด",
  "f_context_bloat_action1": "จบหัวข้อนั้นแล้วเริ่มงานชิ้นต่อไปในเซสชันใหม่",
  "f_context_bloat_action2": "พกพาเฉพาะสิ่งที่งานนั้นต้องใช้จริง ๆ — การลากบันทึกการสำรวจเข้าไปในงานที่ไม่เกี่ยวข้องคือสิ่งที่ทำให้บริบทแพงขนาดนี้",
