  "f_session_churn_body": "%SHORT% จาก %TOTAL% เซสชัน (%PCT%) จบภายใน %TURNS% เทิร์น เซสชันสั้น ๆ ไม่มีวันคืนทุนค่าโหลดบริบทของตัวเองได้ — จ่ายค่าเขียนแคชไปแล้ว แต่ไม่เคยได้ประโยชน์จากการอ่านกลับ",
  "f_session_churn_action": "ก่อนเริ่มเซสชันใหม่ ตรวจดูก่อนว่าคำถามนี้ควรอยู่ในเซสชันที่เปิดอยู่แล้วหรือไม่ ให้มองเซสชันเป็นพื้นที่ทำงานสำหรับหัวข้อหนึ่ง ไม่ใช่กล่องสำหรับคำถามเดียว",
  "f_no_delegation_title": "ไม่พบการมอบหมายงานให้ subagent เลย",
  "f_no_delegation_body": "โทเคนทุกตัวถูกสร้างขึ้นในบทสนทนาหลัก subagent ช่วยกันการอ่านปริมาณมากไว้นอกบริบทหลัก — การค้นหาเกิดขึ้นที่อื่น และมีแค่บทสรุปที่ถูกส่งกลับมา",
