  "f_subagent_fanout_title": "เอาต์พุตส่วนใหญ่มาจาก subagent",
  "f_subagent_fanout_body": "%PCT% ของโทเคนเอาต์พุตทั้งหมดถูกสร้างโดย subagent การมอบหมายเป็นเรื่องดี แต่การมอบหมายที่แต่ละเอเจนต์ต้องสร้างบริบทใหม่ทุกครั้งไม่ใช่เรื่องดี",
  "f_subagent_fanout_action": "ตรวจสอบว่าขนาดการกระจายงานเหมาะสมกับปริมาณงานหรือไม่ การให้เอเจนต์หลายตัวต่างอ่านไฟล์เดียวกันซ้ำ ๆ แพงกว่าให้เอเจนต์เดียวอ่านครั้งเดียว",
