  "f_delegation_balanced_body": "%PCT% ของเอาต์พุตมาจาก subagent — มากพอที่จะกันการอ่านปริมาณมากไว้นอกบริบทหลัก โดยไม่กระจายจนควบคุมไม่อยู่",
  "f_delegation_balanced_action": "ไม่ต้องทำอะไร",
  "f_cache_1h_justified_title": "แคช TTL ยาวกำลังคุ้มค่า",
  "f_cache_1h_justified_body": "%PCT% ของการเขียนแคชใช้ TTL 1 ชั่วโมง และแต่ละโทเคนที่เขียนถูกอ่านกลับเฉลี่ย %RATIO% ครั้ง — สูงกว่าจุดคุ้มทุนที่ประมาณ 3 ครั้งสำหรับส่วนต่างค่าเขียน 2 เท่า",
  "f_cache_1h_justified_action": "ไม่ต้องทำอะไร",
  "f_cache_1h_underused_title": "การเขียนแคช TTL ยาวยังถูกอ่านกลับไม่พอที่จะคุ้มทุน",
  "f_cache_1h_underused_body": "%PCT% ของการเขียนแคชใช้ TTL 1 ชั่วโมง (ราคา 2 เท่าของอินพุต) แต่โทเคนที่เขียนถูกอ่านกลับเพียง %RATIO% ครั้ง TTL 1 ชั่วโมงต้องการการอ่านประมาณสามครั้งจึงจะคุ้มกว่า TTL 5 นาที",
  "f_cache_1h_underused_action": "นี่เป็นสัญญาณเกี่ยวกับความยาวของเซสชัน ไม่ใช่การตั้งค่าที่ต้องเปลี่ยน: TTL ยาวมีไว้เพื่อให้คุณกลับมาได้หลังเว้นช่วง ถ้าคุณไม่ได้กลับมา ปัญหาอยู่ที่ช่วงเว้นนั้นเอง",
  "f_tool_concentration_title": "%TOOL% กินสัดส่วนใหญ่ของการเรียกใช้เครื่องมือทั้งหมด",
  "f_tool_concentration_body": "%TOOL% ถูกเรียกใช้ %CALLS% ครั้ง — คิดเป็น %PCT% ของการเรียกใช้เครื่องมือทั้งหมด %TOTAL% ครั้ง เครื่องมือเดียวที่ครองสัดส่วนขนาดนี้มักหมายถึงขั้นตอนที่ควรเป็นแค่หนึ่งขั้นตอนกลับถูกแบ่งเป็นหลายขั้นตอน",
  "f_tool_concentration_action": "ตรวจดูว่า %TOOL% ถูกเรียกซ้ำ ๆ กับอะไร เป้าหมายเดียวกันที่ถูกเรียกสองครั้งในเซสชันเดียวกันคือบริบทที่คุณมีอยู่แล้ว",
  "f_where_the_time_goes_title": "การลงทุนกับ AI ของคุณกระจุกตัวอยู่ที่ไหน",
  "f_where_the_time_goes_body": "%WS% กินสัดส่วน %PCT% ของค่าใช้จ่ายโดยประมาณตลอด %N% เซสชัน; สามอันดับแรกรวมกันกิน %PCT3%",
  "f_where_the_time_goes_action": "เทียบอันดับนี้กับสิ่งที่คุณคิดว่าเป็นลำดับความสำคัญ พื้นที่ทำงานที่อยู่สูงในรายการนี้แต่อยู่ต่ำในลำดับความสำคัญของคุณเอง คือข้อค้นพบที่แท้จริง",
  "f_working_rhythm_title": "คุณใช้ AI จริง ๆ ตอนไหนบ้าง",
  "f_working_rhythm_body": "ชั่วโมงที่ใช้มากที่สุดคือ %PEAK%:00 (%TURNS% เทิร์น) %PCT% ของเทิร์นตกอยู่นอกช่วง 06:00-22:00",
  "f_working_rhythm_action": "มีประโยชน์ในการตรวจสอบว่าการใช้ AI กำลังแย่งเวลาโฟกัสไปหรือแค่เติมเต็มช่วงว่าง สัดส่วนนอกเวลางานที่สูงก็เป็นเรื่องที่ควรรู้ไว้เอง",
  "f_peak_window_healthy_title": "งานที่คิดราคาตามเวลาตกอยู่นอกช่วงพีคอยู่แล้ว",
  "f_peak_window_healthy_body": "มีเพียง %PCT% ของค่าใช้จ่ายที่ %VENDORS% ของคุณตกอยู่ในช่วงพีค ส่วนต่างที่คุณจ่ายเพราะช่วงเวลานี้อยู่ที่ประมาณ %PREMIUM% ตลอดช่วงเวลานี้",
  "f_peak_window_healthy_action": "ไม่ต้องทำอะไร นี่คือตัวเลขที่ควรจับตาถ้าคุณเริ่มจัดตารางงานแบบแบตช์",
  "f_peak_window_immaterial_title": "งานที่คิดราคาตามเวลาส่วนใหญ่ตกในช่วงพีค แต่ส่วนต่างยังน้อยอยู่",
  "f_peak_window_immaterial_body": "%PCT% ของค่าใช้จ่ายที่ %VENDORS% ของคุณตกอยู่ในช่วงพีค — เป็นแพตเทิร์นเดียวกับเวอร์ชันที่ร้ายแรงกว่าของข้อค้นพบนี้ ที่ปริมาณการใช้ปัจจุบัน ช่วงเวลานี้เพิ่มค่าใช้จ่ายเพียงประมาณ %MONTHLY% ต่อเดือน ยังไม่คุ้มที่จะเปลี่ยนพฤติกรรม",
  "f_peak_window_immaterial_action": "ตอนนี้ยังไม่ต้องทำอะไร ควรกลับมาทบทวนอีกครั้งถ้าปริมาณงานที่คิดราคาตามเวลาของคุณเพิ่มขึ้น: สัดส่วนเดิมคูณด้วยโทเคนสิบเท่าก็หมายถึงส่วนต่างสิบเท่า",
  "f_peak_window_arbitrage_title": "คุณกำลังจ่ายราคาช่วงพีคทั้งที่ไม่จำเป็นต้องจ่าย",
