  "ph_note": "<strong>%P%</strong> ng gastos na naka-presyo ayon sa oras ay napunta sa peak window. Kung sa off-peak tinakbo ang parehong mga turn, %F% sana imbes na %T% — <strong>%X%</strong> na dagdag dahil lang sa timing.",
  "ph_batch": "Ang batch work — paggawa ng test, migration, doc sweep — ang bahaging hindi mo kailangang bantayan, kaya ito ang sulit ilipat.",
  "mon": "Ene,Peb,Mar,Abr,May,Hun,Hul,Ago,Set,Okt,Nob,Dis",
  meth_h2: "Paano nasukat ang mga ito",
  meth_1: "<strong>Hindi kailanman ise-save o ipapakita ang laman ng prompt, sagot, file, command, o path.</strong> Ang naka-save lang ay ang bilang, pangalan ng model, pangalan ng tool, at nakuhang repository o folder label — binasa mula sa token accounting na ibinalik na ng API, sa lokal na transcript ng Claude Code at Codex. Walang gastos na token ang pag-collect.",
  star_ask: "May nakita ka bang dapat baguhin?",
  star_ask_cta: "Bigyan ng star sa GitHub",
  demo_chip: "Sample na data",
  demo_try: "Subukan mo",
  meth_2: "<strong>Tantiya ang gastos, hindi bill.</strong> Eksakto ang bilang ng token; ang halaga sa dolyar ay gumagamit ng pampublikong list price ng API ng bawat vendor (na-verify %V%) — ang pinakamataas na bayad ninuman, bago ang enterprise o subscription na diskuwento. Ituring ang gastos bilang pinakamataas na hangganan, at bilang <em>relatibong</em> senyas kung saan napupunta ang pagsisikap.",
  meth_3: "<strong>Naka-attribute ang trabaho ayon sa repository, hindi sa account.</strong> Naka-credit ang isang turn sa repo na hinawakan nito, o minamana nito ang pinakamalapit na naka-attribute na turn sa parehong session; nananatiling <code>unattributed</code> ang session na walang hinawakang file, at hindi naka-tali sa tunay na repo ang mga scratch o config folder. Galing sa panuntunang isinulat mo mismo sa <code>engine/topology.json</code> ang lane — walang dalang pagkakakilanlan ng account ang transcript.",
