  "ph_note": "<strong>%P%</strong> do gasto precificado por horário caiu em uma janela de pico. Rodar os mesmos turnos fora de pico teria custado %F% em vez de %T% — um prêmio de <strong>%X%</strong> só pelo horário.",
  "ph_batch": "Trabalho em lote — geração de testes, migrações, varreduras de documentação — é a parte que não precisa de você olhando e, por isso, a que vale mover.",
  "mon": "jan,fev,mar,abr,mai,jun,jul,ago,set,out,nov,dez",
  meth_h2: "Como isso foi medido",
  meth_1: "<strong>Conteúdo de prompt, resposta, arquivo, comando ou caminho nunca é armazenado nem exibido.</strong> Só ficam guardadas contagens, nomes de modelo, nomes de ferramenta e rótulos de repositório/pasta derivados — lidos da contagem de tokens que a API já retorna, em transcrições locais do Claude Code e do Codex. A coleta não consome nenhum token.",
  star_ask: "Encontrou algo que vale a pena mudar?",
  star_ask_cta: "Dê uma estrela no GitHub",
  demo_chip: "Dados de exemplo",
  demo_try: "Experimente você",
  meth_2: "<strong>O custo é uma estimativa, não uma fatura.</strong> As contagens de tokens são exatas; os valores em dólar aplicam o preço de tabela público da API de cada fornecedor (verificado em %V%) — a maior tarifa que alguém paga, antes de descontos corporativos ou de assinatura. Trate o gasto como um teto e como um sinal <em>relativo</em> de para onde vai o esforço.",
  meth_3: "<strong>O trabalho é atribuído por repositório, não por conta.</strong> Um turno é creditado ao repositório que tocou, ou herda o turno atribuído mais próximo na mesma sessão; uma sessão que não tocou em nada permanece <code>unattributed</code>, e pastas de rascunho ou config não se vinculam a repositórios reais. As trilhas vêm de uma regra que você mesmo escreve em <code>engine/topology.json</code> — as transcrições não carregam identidade de conta.",
