  "f_local_currency_action": "Nenhuma ação. O câmbio neste repositório é indicativo e mantido manualmente — trate como uma conferência aproximada, não como contabilidade.",
  "f_duplicated_turns_title": "Alguns turnos estão sendo contados mais de uma vez",
  "f_duplicated_turns_body": "%DUPES% dos %TOTAL% turnos no armazenamento (%SHARE%) são repetições de um turno que já existia, então todos os totais desta página — turnos, tokens e gasto — estão altos demais nessa proporção. Isso é um armazenamento corrompido, não uso real: uma sincronização interrompida, duas sincronizações simultâneas, ou um `sync --full` executado antes de o reparo entrar. As duplicatas são idênticas em fornecedor, sessão, timestamp, turno e contagem de tokens, o que é exatamente o que permite identificá-las.",
  "f_duplicated_turns_action1": "Rode `python3 observe.py dedupe` e depois `python3 observe.py digest report`. Ele mantém a primeira cópia de cada turno e é seguro rodar em um armazenamento saudável.",
