  "f_unpriced_models_title": "Parte desta estimativa é um chute",
  "f_unpriced_models_body": "%SHARE% do gasto estimado (%COST% em %TURNS% turnos) veio de modelos que a tabela de preços não nomeia: %NAMED%. Esses turnos foram precificados na tarifa genérica de reserva de %FB_IN%/M de entrada e %FB_OUT%/M de saída, que é um valor provisório, não a tarifa publicada por esse fornecedor. O resto da página não consegue dizer para que lado esse erro pende.",
