  "mon": "ene,feb,mar,abr,may,jun,jul,ago,sep,oct,nov,dic",
  meth_h2: "Cómo se midió esto",
  meth_1: "<strong>El contenido de prompts, respuestas, archivos, comandos o rutas nunca se guarda ni se muestra.</strong> Solo se conservan recuentos, nombres de modelo, nombres de herramienta y etiquetas de repositorio o carpeta derivadas — leídas del recuento de tokens que la API ya devuelve, en transcripciones locales de Claude Code y Codex. La recopilación no consume ni un token.",
