  meth_2: "<strong>El costo es una estimación, no una factura.</strong> Los recuentos de tokens son exactos; las cifras en dólares aplican el precio de lista público de la API de cada proveedor (verificado %V%): la tarifa más alta que paga cualquiera, antes de descuentos empresariales o de suscripción. Trata el gasto como un techo y como una señal <em>relativa</em> de adónde va el esfuerzo.",
