  "f_cache_write_never_read_action": "Haz las preguntas de seguimiento en la misma sesión — es en el segundo turno cuando la caché empieza a amortizarse. Estas sesiones se cerraron justo después de cargar el primer contexto grande.",
  "f_premium_tier_light_turns_title": "Los modelos premium están gestionando muchos turnos muy breves",
  "f_premium_tier_light_turns_body": "En %TURNS% turnos de nivel premium, la salida promedio es de %AVG% tokens — por debajo de %THRESHOLD%. Los turnos breves suelen ser confirmaciones, búsquedas o ediciones mecánicas, que un nivel más barato resuelve igual de bien.",
  "f_premium_tier_light_turns_action": "Deriva el trabajo mecánico (leer archivos, renombrar, editar una línea, comprobar el estado) a Sonnet o Haiku, o ejecútalo con un esfuerzo de razonamiento bajo. Reserva el nivel premium para los turnos en los que la profundidad de razonamiento realmente cambia la respuesta.",
  "f_read_heavy_no_change_title": "Sesiones que leyeron mucho y no cambiaron nada",
  "f_read_heavy_no_change_body": "%N% sesión(es) hicieron %READS% llamadas a herramientas de tipo lectura sin ninguna edición ni escritura, con un costo de %COST% USD. Parte es investigación real; parte es buscar a tientas algo que una búsqueda certera habría encontrado directamente.",
  "f_read_heavy_no_change_action1": "Delega preguntas del tipo 'dónde está X' a un subagente de búsqueda — la respuesta vuelve sin el contenido completo del archivo.",
  "f_read_heavy_no_change_action2": "Pregunta directamente lo que quieres saber, en lugar de leer a ver si lo encuentras.",
  "f_context_bloat_title": "Algunas sesiones cargan un contexto muy grande por turno",
  "f_context_bloat_body": "%N% sesión(es) alcanzaron un pico por encima de %THRESHOLD% tokens en un solo turno (el peor: %WORST%), y cada turno posterior lo vuelve a leer entero.",
  "f_context_bloat_action1": "Cierra ese hilo de trabajo y empieza la siguiente tarea en una sesión nueva.",
  "f_context_bloat_action2": "Lleva contigo solo lo que ese trabajo realmente necesita — arrastrar toda una transcripción de exploración a un trabajo sin relación es lo que hace el contexto tan caro.",
  "f_session_churn_title": "Buena parte de las sesiones dura solo unos pocos turnos",
  "f_session_churn_body": "%SHORT% de %TOTAL% sesiones (%PCT%) terminaron en %TURNS% turnos o menos. Las sesiones cortas nunca amortizan su propio costo de carga de contexto — el gasto de escritura en caché ya se pagó, pero la lectura nunca llega a producirse.",
  "f_session_churn_action": "Antes de empezar una sesión nueva, comprueba si esa pregunta pertenece a una sesión que ya tienes abierta. Trata una sesión como un espacio de trabajo para un tema, no como un recipiente para una pregunta.",
  "f_no_delegation_title": "No se observa ninguna delegación a subagentes",
  "f_no_delegation_body": "Todos los tokens se produjeron en la conversación principal. Los subagentes mantienen las lecturas masivas fuera de tu contexto principal — la búsqueda ocurre en otro lugar y solo vuelve la conclusión.",
  "f_no_delegation_action": "Para preguntas amplias del tipo 'encuentra todos los lugares donde…', delega. El contexto principal se mantiene pequeño, lo que abarata cada turno posterior.",
  "f_subagent_fanout_title": "La mayor parte de la salida viene de subagentes",
  "f_subagent_fanout_body": "El %PCT% de todos los tokens de salida fue producido por subagentes. Delegar es bueno; delegar de un modo que reconstruye el contexto en cada agente no lo es.",
  "f_subagent_fanout_action": "Comprueba si el tamaño de la distribución coincide con el trabajo. Varios agentes que cada uno vuelve a leer los mismos archivos cuesta más que un agente que los lee una sola vez.",
  "f_delegation_balanced_title": "La delegación a subagentes parece proporcionada",
  "f_delegation_balanced_body": "El %PCT% de la salida vino de subagentes — suficiente para mantener las lecturas masivas fuera del contexto principal sin una distribución descontrolada.",
  "f_delegation_balanced_action": "Sin acción.",
  "f_cache_1h_justified_title": "La caché de TTL largo se está amortizando",
  "f_cache_1h_justified_body": "El %PCT% de las escrituras en caché usaron el TTL de 1 hora, y cada token escrito se vuelve a leer en promedio %RATIO% veces — por encima del punto de equilibrio de ~3x necesario para el recargo de escritura de 2x.",
  "f_cache_1h_justified_action": "Sin acción.",
  "f_cache_1h_underused_title": "Las escrituras en caché con TTL largo no se releen lo suficiente para amortizarse",
  "f_cache_1h_underused_body": "El %PCT% de las escrituras en caché usaron el TTL de 1 hora (2x el precio de entrada), pero los tokens escritos solo se vuelven a leer %RATIO% veces. El TTL de 1 hora necesita unas tres lecturas para superar al de 5 minutos.",
  "f_cache_1h_underused_action": "Esto es una señal sobre la duración de la sesión, no un ajuste que cambiar: el TTL largo existe para que puedas volver después de una pausa. Si no estás volviendo, el problema está en esa pausa misma.",
  "f_tool_concentration_title": "%TOOL% acapara una gran parte de todas las llamadas a herramientas",
  "f_tool_concentration_body": "%TOOL% se llamó %CALLS% veces — el %PCT% de las %TOTAL% llamadas a herramientas en total. Que una sola herramienta domine tanto suele significar un flujo que podría ser un solo paso y terminó siendo varios.",
  "f_tool_concentration_action": "Revisa sobre qué se repite %TOOL%. El mismo objetivo llamado dos veces en una sesión es contexto que ya tenías.",
  "f_where_the_time_goes_title": "Dónde se concentra tu inversión en IA",
