  "f_where_the_time_goes_action": "Compara este ranking con lo que dirías que son tus prioridades. Un espacio de trabajo alto en esta lista y bajo en tu propia lista de prioridades — esa es la conclusión.",
  "f_working_rhythm_title": "Cuándo usas AI en realidad",
  "f_working_rhythm_body": "La hora punta es las %PEAK%:00 (%TURNS% turnos). El %PCT% de los turnos caen fuera de 06:00-22:00.",
  "f_working_rhythm_action": "Útil como chequeo de si el uso de IA está desplazando tiempo de concentración o llenando huecos. Un porcentaje alto fuera del horario también merece conocerse por sí mismo.",
  "f_peak_window_healthy_title": "El trabajo con tarifa por horario ya cae fuera de la hora punta",
