  "f_peak_window_healthy_action": "Sin acción. Es el número a vigilar si empiezas a programar tareas por lotes.",
  "f_peak_window_immaterial_title": "La mayor parte del trabajo con tarifa por horario corre en hora punta, pero el recargo aún es pequeño",
  "f_peak_window_immaterial_body": "El %PCT% de tu gasto en %VENDORS% cayó dentro de una franja punta — el mismo patrón que la versión grave de esta conclusión. Con el volumen actual, ese horario solo cuesta unos %MONTHLY% al mes, que no justifica cambiar un hábito.",
  "f_peak_window_immaterial_action": "Nada que hacer por ahora. Vale la pena revisarlo si tu volumen con tarifa por horario crece: el mismo porcentaje sobre diez veces más tokens es diez veces más recargo.",
  "f_peak_window_arbitrage_title": "Estás pagando tarifas de hora punta que no tenías por qué pagar",
  "f_peak_window_arbitrage_body": "El %PCT% de tu gasto con tarifa por horario (%VENDORS%) corrió dentro de una franja punta, donde los mismos tokens pueden costar hasta el doble de la tarifa valle. Ese horario costó unos %PREMIUM% en el período.",
  "f_peak_window_arbitrage_action1": "Programa para la hora valle el trabajo que no necesita supervisión — generación de pruebas, migraciones, limpieza de documentación, refactorizaciones grandes.",
  "f_peak_window_arbitrage_action2": "Deja el trabajo interactivo donde está: el recargo compra tu atención inmediata, y un trabajo por lotes no la necesita.",
  "f_peak_window_arbitrage_action3": "Estas franjas son estrechas — DeepSeek es 01:00-04:00 y 06:00-10:00 UTC, GLM es 14:00-18:00 UTC+8 en días laborables, así que los fines de semana quedan totalmente libres de esto.",
  "f_plan_under_used_title": "%LABEL% cuesta más de lo que estás aprovechando",
  "f_plan_under_used_body": "En los últimos %DAYS% días, tu uso valió unos %API%/mes a tarifas de API por medición. Pagas %PAID%/mes. Estás pagando por un margen que no estás usando.",
  "f_plan_under_used_action": "Baja de nivel de plan, o traslada deliberadamente más trabajo a este plan — el plan ya está pagado, así que cualquier cosa que sigas haciendo a mano se puede delegar gratis hasta cruzar esa línea.",
  "f_plan_value_realised_title": "%LABEL% devolvió cerca de %MULT% de lo que pagaste",
  "f_plan_value_realised_body": "En los últimos %DAYS% días, tu uso valió unos %API%/mes a tarifas de API por medición, frente a un plan de %PAID%/mes. Las cifras en dólares en el resto de esta página son un precio sombra — lo que este trabajo habría costado si se midiera — no una factura que realmente recibiste.",
  "f_plan_value_realised_action": "Sin acción. Vale la pena revisarlo tras cualquier cambio de nivel, y conocerlo antes de pedir un plan más grande.",
  "f_vendor_mix_healthy_title": "El trabajo está repartido entre más de un proveedor",
