  "f_vendor_mix_healthy_action": "Sin acción. Es esa combinación la que te permite renegociar el precio o cambiar de proveedor sin tener que reaprender un flujo de trabajo.",
  "f_vendor_concentration_title": "Casi todo pasa por %TOP%",
  "f_vendor_concentration_body": "El %PCT% de tus tokens de salida vino de %TOP%. Los cambios de tarifa, la disponibilidad regional y las interrupciones de ese único proveedor se convierten en un punto único de fallo para todo tu flujo de trabajo — y no tienes una base medida con la que comparar el costo de cambiar.",
  "f_vendor_concentration_action": "Ejecuta un tipo de trabajo recurrente y de bajo riesgo (esqueletos de pruebas, mensajes de commit, actualizaciones de documentación) en un segundo proveedor durante dos semanas. El objetivo no es ahorrar dinero de inmediato, sino saber cuánto costaría cambiar antes de verte obligado a hacerlo.",
  "f_local_currency_title": "Cuánto cuesta esto donde estás",
