  "f_duplicated_turns_title": "Algunos turnos se están contando más de una vez",
  "f_duplicated_turns_body": "%DUPES% de %TOTAL% turnos en el almacén (%SHARE%) son repeticiones de un turno ya existente, así que todos los totales de esta página — turnos, tokens y gasto — están inflados en esa misma proporción. Esto es un almacén dañado, no uso real: una sincronización interrumpida, dos sincronizaciones a la vez, o un `sync --full` ejecutado antes de que se aplicara la corrección. Los duplicados son idénticos en proveedor, sesión, marca de tiempo, turno y recuento de tokens, que es precisamente lo que permite identificarlos.",
  "f_duplicated_turns_action1": "Ejecuta `python3 observe.py dedupe` y luego `python3 observe.py digest report`. Conserva la primera copia de cada turno y es seguro ejecutarlo en un almacén sano.",
